/**
 * templates/leg.ts — Legislação de Telecomunicações question bank.
 *
 * Content follows the Cartilha do Serviço Radioamador, versão 2026-06
 * (Anexo 2, pp. 39–53) and the Ato nº 3448/2026 itself (Requisitos
 * Operacionais), which the Cartilha transcribes in part.
 *
 * Topic mapping (ementa item → what goes there):
 * - rr-uit: Regulamento de Rádio, Art. 25 (Anexo 2, p. 39–40).
 * - recomendacao-itu-r-m1544: minimum qualifications (p. 40).
 * - plano-iaru-regiao-2: IARU, its regions, call-sign series, band plan (pp. 40–41).
 * - lgt: definitions, Anatel, regimes, sanctions (§2, pp. 43–44).
 * - rgst: the service, licences, COER classes, authorisations, exams,
 *   IARP and foreign operators (§§3–4, §6; Ato items 4, 5, 7, 8, 11).
 * - requisitos-tecnicos-operacionais: call signs, operating rules and
 *   repeaters (§1, §5, §8, §13; Ato items 10 and 12).
 * - plano-de-atribuicao: band restrictions, calling frequency, power and
 *   e.i.r.p. limits (§§9–10).
 * - homologacao: certification and homologation (§7, §11).
 *
 * Quality standard: considerations/BRAINSTORM.md §5. Builders: ./helpers.ts.
 */
import type { QuestionDraft } from "../schema";
import { createBuilder, cite } from "./helpers";

// Full AI review of every item in this file against the Cartilha 2026-06
// text and the Ato 3448/2026 PDF, done 2026-10-13. Items added later must
// pass `checkedByAi: false` in their Meta until they are checked.
const { tf, mc } = createBuilder("LEG", { checkedByAi: true });

/** Numbered Anexo 2 section, optionally with the Ato item it transcribes. */
const a2 = (sec: string, page: number | string, atoItem?: string) =>
  cite.annex(2, sec, page, atoItem ? `; Ato 3448/2026, item ${atoItem}` : "");
/** Unnumbered Anexo 2 part (the RR, M.1544 and IARU summaries). */
const part = (name: string, page: number | string) => cite.annexPart(2, name, page);
const RR = "Regulamento de Rádio (UIT)";
const M1544 = "Recomendação ITU-R M.1544-1";
const IARU = "Plano de Faixas IARU Região 2";
/** Ato-only reference, for items the Cartilha does not transcribe. */
const ato = cite.ato;

/* ── 1. Regulamento de Rádio da UIT (Anexo 2, pp. 39–40) ───────────────── */

